insert into public.recipes (id, household_id, title, description, image_url, source_type, source_url, servings, prep_min, cook_min, instructions, nutrition, tags, cuisine, visibility, created_by)
values
  ('1edff2da-232f-50a0-8168-0a5a7deff04d', null, 'Baked Chicken Parmesan with Spaghetti', 'Breaded chicken cutlets baked with mild marinara and melted mozzarella, served over spaghetti. Soft, cheesy, and gently seasoned.', null, 'ai', null, 4, 25, 30, '[{"step":1,"text":"Heat the oven to 425 F. Brush a rimmed baking sheet with 1 tbsp of the olive oil."},{"step":2,"text":"Pound the chicken cutlets to an even 1/2 inch thickness. Season both sides with the 1 tsp kosher salt."},{"step":3,"text":"Set out three shallow dishes. Put the flour in the first, the beaten eggs in the second, and the breadcrumbs mixed with the Parmesan and garlic powder in the third."},{"step":4,"text":"Dredge each cutlet in flour, then egg, then the breadcrumb mix. Press so the crumbs stick. Place on the baking sheet and drizzle with the remaining 2 tbsp olive oil."},{"step":5,"text":"Bake for 15 minutes, until the crumbs are golden on top."},{"step":6,"text":"Spoon about 1/4 cup marinara over each cutlet and top with the mozzarella. Bake 8 to 10 minutes more, until the cheese is melted and the chicken reaches 165 F."},{"step":7,"text":"While the chicken bakes, bring the water and 1 tbsp salt to a boil in a large pot. Cook the spaghetti for 9 to 11 minutes, until tender, then drain."},{"step":8,"text":"Warm the remaining marinara in the empty pot. Toss in the spaghetti."},{"step":9,"text":"Serve each cutlet over a pile of spaghetti. Cool leftovers fully before freezing the chicken and pasta in separate containers."}]'::jsonb, null, array['dinner', 'chicken', 'bake', 'kid_friendly', 'freezer_friendly']::text[], 'italian', 'catalog', null),
  ('41c8c49e-3388-572b-a5fb-82bad2950675', null, 'Baked Cod with Cherry Tomatoes, Olives, and Capers', 'Cod fillets baked over juicy cherry tomatoes with briny olives and capers. The flavors are bright, salty, and garlicky, with a little lemon.', null, 'ai', null, 4, 10, 18, '[{"step":1,"text":"Heat the oven to 425 F. Pat the cod dry with paper towels."},{"step":2,"text":"In a 9x13 inch baking dish, toss the tomatoes with 2 tbsp olive oil, the garlic, olives, capers, oregano, red pepper flakes, and 1/4 tsp salt."},{"step":3,"text":"Roast the tomatoes for 8 minutes, until they start to soften and split."},{"step":4,"text":"Rub the cod with the remaining 1 tbsp olive oil. Season both sides with the remaining 1/2 tsp salt and the black pepper."},{"step":5,"text":"Nestle the fillets into the tomatoes and spoon some of the tomatoes over the top."},{"step":6,"text":"Bake for 10 to 12 minutes, until the fish is opaque and flakes easily and reads 145 F in the thickest part."},{"step":7,"text":"Squeeze 2 lemon wedges over the dish and scatter with parsley. Serve with the remaining wedges and the pan juices."}]'::jsonb, null, array['dinner', 'fish', 'gluten_free', 'dairy_free', 'bake']::text[], 'mediterranean', 'catalog', null),
  ('e24eaacd-8730-5cdd-837e-b75b98d59e61', null, 'Baked Teriyaki Tofu Bowls with Broccoli', 'Cubes of baked tofu glazed in a mild, sweet soy sauce, served over rice with tender broccoli. Gentle flavors with no heat.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Heat the oven to 425 F. Line a rimmed baking sheet with parchment."},{"step":2,"text":"Combine the rice and 3 cups water in a medium pot. Bring to a boil, cover, and cook on low for 15 minutes until the water is absorbed."},{"step":3,"text":"Whisk the soy sauce, maple syrup, rice vinegar, cornstarch, ginger, garlic powder, and 1/4 cup water in a small saucepan."},{"step":4,"text":"Cook the sauce over medium heat for 2 to 3 minutes, stirring, until it thickens and coats a spoon."},{"step":5,"text":"Toss the tofu with half of the sauce in a bowl. Spread it on one half of the baking sheet."},{"step":6,"text":"Toss the broccoli with the oil and salt. Spread it on the other half of the sheet."},{"step":7,"text":"Bake for 20 minutes, stirring once at 10 minutes, until the tofu is browned at the edges and the broccoli is tender with browned tips."},{"step":8,"text":"Fluff the rice with a fork. Divide it among four bowls and top with tofu and broccoli."},{"step":9,"text":"Drizzle the remaining sauce over each bowl."}]'::jsonb, null, array['dinner', 'tofu', 'vegetarian', 'vegan', 'dairy_free', 'bake', 'kid_friendly']::text[], 'japanese', 'catalog', null),
  ('52bf281e-91bf-5a77-9025-58ed80434ac7', null, 'Beef and Broccoli Stir Fry', 'Tender sliced beef and broccoli in a mild, lightly sweet ginger sauce made with coconut aminos, served over rice. Gentle flavors that suit kids.', null, 'ai', null, 4, 15, 15, '[{"step":1,"text":"Combine the rice, 3 cups water, and 1/4 tsp of the salt in a saucepan. Bring to a boil, cover, and cook on low for 15 minutes until the water is absorbed."},{"step":2,"text":"Toss the sliced beef with 1 tbsp cornstarch in a bowl until lightly coated."},{"step":3,"text":"Whisk the coconut aminos, 1/2 cup water, ginger, 1 tsp cornstarch, and maple syrup in a small bowl."},{"step":4,"text":"Heat 1 tbsp oil in a 12-inch skillet over medium-high heat. Add half the beef in a single layer and cook 2 minutes per side until browned. Move to a plate and repeat with 1 tbsp oil and the remaining beef."},{"step":5,"text":"Add the last 1 tbsp oil to the skillet. Add the broccoli, the remaining salt, and 2 tbsp water from the sauce bowl''s measure if the pan looks dry, then cook 4 minutes until bright green and just tender."},{"step":6,"text":"Add the garlic and stir for 30 seconds until fragrant."},{"step":7,"text":"Return the beef to the pan and pour in the sauce. Stir for 2 minutes until the sauce thickens and the beef reaches 145 F."},{"step":8,"text":"Fluff the rice with a fork and serve the beef and broccoli over it."}]'::jsonb, null, array['dinner', 'beef', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly']::text[], 'chinese', 'catalog', null),
  ('ec188bf2-484d-5864-8229-f609a91affd7', null, 'One Pot Black Bean and Rice Burrito Bowls', 'Rice, black beans, and sweet corn simmered together in one pot, then topped with mild salsa and fresh avocado. Soft, savory, and gentle in flavor.', null, 'ai', null, 4, 10, 20, '[{"step":1,"text":"Heat the olive oil in a large pot with a lid over medium heat. Add the onion and cook for 4 minutes, until soft."},{"step":2,"text":"Stir in the garlic, cumin, and paprika. Cook for 30 seconds, until fragrant."},{"step":3,"text":"Add the rice and stir for 1 minute to coat it in the oil."},{"step":4,"text":"Pour in the water and add the salt. Bring to a boil, then stir in the black beans."},{"step":5,"text":"Cover, reduce the heat to low, and cook for 15 minutes, until the rice is tender and the water is absorbed."},{"step":6,"text":"Scatter the frozen corn over the rice, cover again, and let it stand off the heat for 5 minutes, until the corn is hot."},{"step":7,"text":"Fluff everything together with a fork. Stir in 1/2 cup of the salsa."},{"step":8,"text":"Divide among 4 bowls. Top with the remaining salsa and the diced avocado."}]'::jsonb, null, array['dinner', 'beans', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot', 'kid_friendly', 'pantry', 'leftovers']::text[], 'mexican', 'catalog', null),
  ('e38073aa-c763-58f6-8145-d41d97ac4100', null, 'Black Bean Tacos with Cabbage Slaw', 'Soft corn tortillas filled with mild, lightly spiced black beans, crunchy lime cabbage slaw, and creamy avocado. Gentle in flavor and quick to make.', null, 'ai', null, 4, 12, 10, '[{"step":1,"text":"Toss the cabbage with the lime juice, 1 tbsp olive oil, and 1/4 tsp salt in a bowl. Set aside."},{"step":2,"text":"Heat 2 tbsp olive oil in a 12 inch skillet over medium heat for 1 minute."},{"step":3,"text":"Add the black beans, cumin, paprika, garlic powder, and 1/2 tsp salt. Stir for 1 minute."},{"step":4,"text":"Pour in the water. Cook 5 to 6 minutes, mashing about a third of the beans with a spoon, until thick and creamy."},{"step":5,"text":"Move the beans to a bowl and wipe out the skillet. Return it to medium-high heat."},{"step":6,"text":"Warm each tortilla in the dry skillet for 30 seconds per side, until soft and lightly browned in spots."},{"step":7,"text":"Fill each tortilla with beans, a handful of slaw, and a few slices of avocado. Serve right away."}]'::jsonb, null, array['dinner', 'beans', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly', 'pantry']::text[], 'mexican', 'catalog', null),
  ('cad39c86-def5-5328-bfec-c5b8ee59ddec', null, 'Coconut Chicken and Chickpea Curry', 'A one pot Indian-style curry of chicken thighs and chickpeas in a spiced coconut tomato sauce. It is creamy, warm, and mildly spicy, and it tastes even better the next day.', null, 'ai', null, 4, 10, 25, '[{"step":1,"text":"Heat the oil in a large deep skillet or Dutch oven over medium heat. Add the onion and cook for 4 minutes, until soft."},{"step":2,"text":"Stir in the garlic and ginger and cook for 30 seconds, until fragrant."},{"step":3,"text":"Add the chicken, salt, and pepper. Cook for 4 minutes, stirring, until the outside is no longer pink."},{"step":4,"text":"Stir in the curry powder, cumin, and turmeric. Cook for 1 minute so the spices toast."},{"step":5,"text":"Add the tomatoes, coconut milk, chickpeas, and water. Scrape up any browned bits from the bottom of the pot."},{"step":6,"text":"Bring to a gentle boil, then reduce the heat to medium-low. Simmer uncovered for 15 minutes, stirring now and then, until the sauce thickens."},{"step":7,"text":"Check that the chicken reads 165 F in the thickest piece. Taste and add more salt if needed."},{"step":8,"text":"Serve hot. The curry thickens as it sits, so add a splash of water when reheating leftovers."}]'::jsonb, null, array['dinner', 'chicken', 'gluten_free', 'dairy_free', 'one_pot', 'pantry', 'leftovers']::text[], 'indian', 'catalog', null),
  ('fac3c25b-9580-502c-a8be-6b52095545f0', null, 'Skillet Chicken Fajitas in Corn Tortillas', 'Strips of chicken cooked with sweet bell peppers and onion in a mild spice mix, served in warm corn tortillas. Soft, savory, and not spicy.', null, 'ai', null, 4, 15, 15, '[{"step":1,"text":"Toss the chicken strips in a bowl with 1 tbsp olive oil, paprika, cumin, garlic powder, salt, and pepper until evenly coated."},{"step":2,"text":"Heat 1 tbsp olive oil in a 12 inch skillet over medium-high heat until it shimmers."},{"step":3,"text":"Add the chicken in a single layer. Cook 5 to 6 minutes, stirring once or twice, until browned and no longer pink inside. Move it to a plate."},{"step":4,"text":"Add the remaining 1 tbsp olive oil to the skillet. Add the peppers and onion."},{"step":5,"text":"Cook 5 to 6 minutes, stirring often, until soft and lightly browned at the edges."},{"step":6,"text":"Return the chicken and any juices to the skillet. Stir for 1 to 2 minutes until the chicken reads 165 F on a thermometer."},{"step":7,"text":"Turn off the heat and stir in the lime juice."},{"step":8,"text":"Warm the tortillas one at a time in a dry pan over medium heat, about 30 seconds per side, until soft and flexible. Fill each with the chicken mixture and serve."}]'::jsonb, null, array['dinner', 'chicken', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly']::text[], 'mexican', 'catalog', null),
  ('a80cc61c-b942-57b9-81a3-2d98b8a30679', null, 'Chicken Fried Rice with Eggs, Peas, and Carrots', 'A mild skillet fried rice with diced chicken, scrambled eggs, peas, and carrots. It tastes savory and lightly salty from soy sauce.', null, 'ai', null, 4, 10, 15, '[{"step":1,"text":"Break up any clumps in the cold rice with your hands. Beat the eggs in a small bowl with a pinch of the salt."},{"step":2,"text":"Heat 1 tbsp oil in a 12 inch nonstick skillet over medium-high heat. Pour in the eggs and stir until just set, about 1 minute. Move them to a plate."},{"step":3,"text":"Add 1 tbsp oil to the skillet. Add the chicken, the remaining salt, and the white pepper. Cook, stirring now and then, for 5 to 6 minutes, until browned and no pink remains."},{"step":4,"text":"Move the chicken to the plate with the eggs. Add the remaining 1 tbsp oil, the peas, and the carrots to the skillet. Cook for 2 minutes, until hot."},{"step":5,"text":"Add the garlic and cook for 30 seconds, until fragrant."},{"step":6,"text":"Add the rice and soy sauce. Stir and press the rice into the pan for 3 to 4 minutes, until hot and slightly toasted."},{"step":7,"text":"Return the chicken and eggs to the skillet, breaking the eggs into small pieces. Check that the chicken reads 165 F, then stir in the green onions and serve."}]'::jsonb, null, array['dinner', 'chicken', 'dairy_free', 'skillet', 'kid_friendly', 'pantry']::text[], 'chinese', 'catalog', null),
  ('ced0f5ae-ee3a-5879-9b8d-9610cf23aca3', null, 'Chicken Piccata with Spaghetti', 'Thin chicken cutlets pan-fried until golden, then simmered in a bright butter sauce with lemon and capers. Served over spaghetti. Tangy, salty, and rich.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Bring a large pot of salted water to a boil. Cook the spaghetti for 9 to 10 minutes until tender, then drain."},{"step":2,"text":"Pat the chicken dry. Mix the flour, salt, and pepper on a plate and coat each cutlet, shaking off extra."},{"step":3,"text":"Heat the oil and 1 tbsp butter in a 12 inch skillet over medium-high heat. Cook the cutlets 3 to 4 minutes per side until golden and 165 F inside, working in two batches if needed."},{"step":4,"text":"Move the chicken to a plate and cover it with foil."},{"step":5,"text":"Lower the heat to medium. Add the garlic to the skillet and stir for 30 seconds."},{"step":6,"text":"Pour in the broth and lemon juice. Scrape up the browned bits and simmer 4 to 5 minutes until reduced by about a third."},{"step":7,"text":"Stir in the capers and the remaining 3 tbsp butter until the sauce is smooth."},{"step":8,"text":"Return the chicken and any juices to the pan and spoon sauce over it for 1 minute."},{"step":9,"text":"Toss the spaghetti with some of the sauce. Serve topped with the chicken, more sauce, and parsley."}]'::jsonb, null, array['dinner', 'chicken', 'skillet']::text[], 'italian', 'catalog', null),
  ('fabcb7b7-6b71-59c2-9e4f-60c4595b2585', null, 'Greek Chicken Souvlaki Rice Bowls', 'Grilled lemon oregano chicken over rice with a crisp cucumber tomato salad. The dressing is bright with lemon and garlic.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Combine the rice, water, and 1/2 tsp salt in a medium pot. Bring to a boil, cover, and reduce to low. Cook 15 minutes until the water is absorbed, then rest covered 5 minutes."},{"step":2,"text":"Whisk the olive oil, lemon juice, garlic, oregano, 1 tsp salt, and pepper in a bowl. This is the dressing."},{"step":3,"text":"Put the chicken in a bowl with half of the dressing. Toss to coat and let it sit while the grill heats."},{"step":4,"text":"Heat a grill or grill pan to medium-high. Thread the chicken onto metal skewers, or grill the pieces in a grill basket."},{"step":5,"text":"Grill the chicken 10 to 12 minutes, turning every 3 minutes, until browned and an instant-read thermometer reads 165 F."},{"step":6,"text":"Toss the cucumber, tomatoes, and red onion with 2 tbsp of the remaining dressing."},{"step":7,"text":"Fluff the rice and divide it among 4 bowls. Top with the chicken and the salad."},{"step":8,"text":"Drizzle the remaining dressing over each bowl and serve."}]'::jsonb, null, array['dinner', 'chicken', 'gluten_free', 'dairy_free', 'grill']::text[], 'greek', 'catalog', null),
  ('43d24bcc-5d3c-5a3e-9ff6-2258c7670301', null, 'Skillet Chicken Teriyaki Rice Bowls', 'Tender chicken pieces in a mild, lightly sweet ginger garlic glaze, served over rice with steamed broccoli. The sauce is made from coconut aminos and has no heat.', null, 'ai', null, 4, 10, 20, '[{"step":1,"text":"Combine the rice, 3 cups water, and salt in a medium pot. Bring to a boil, cover, and reduce to low. Cook 15 minutes until the water is absorbed, then rest covered."},{"step":2,"text":"Whisk the coconut aminos, maple syrup, garlic, and ginger in a small bowl. In a second small bowl, stir the arrowroot into 2 tbsp cold water."},{"step":3,"text":"Heat the oil in a 12 inch skillet over medium-high heat. Add the chicken in one layer and cook 5 to 6 minutes, turning once, until browned."},{"step":4,"text":"Pour the aminos mixture into the skillet. Simmer 3 minutes, stirring, until the chicken reaches 165 F inside."},{"step":5,"text":"Stir the arrowroot mixture again and add it to the skillet. Cook 1 minute until the sauce is glossy and coats the chicken. Move the chicken and sauce to a plate."},{"step":6,"text":"Wipe the skillet and add the broccoli and 1/4 cup water. Cover and steam over medium heat 4 to 5 minutes until bright green and tender when pierced with a fork."},{"step":7,"text":"Fluff the rice with a fork and divide among four bowls. Top with the chicken, sauce, and broccoli."}]'::jsonb, null, array['dinner', 'chicken', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly']::text[], 'japanese', 'catalog', null),
  ('8f776318-52aa-5104-b3fc-a991a277226d', null, 'Chicken Tikka Masala with Basmati Rice', 'Tender chicken pieces simmered in a spiced tomato cream sauce, served over basmati rice. The sauce is rich, warm, and lightly tangy. It tastes even better the next day.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Combine the rice, water, and 1/2 tsp salt in a medium pot. Bring to a boil, cover, and reduce the heat to low. Cook 15 minutes, then rest off the heat, covered, until the water is absorbed."},{"step":2,"text":"Toss the chicken with 1 tsp salt. Heat the oil in a 12 inch skillet over medium-high heat."},{"step":3,"text":"Add the chicken in one layer and cook 4 minutes, stirring once, until lightly browned. Move it to a plate. It will not be cooked through yet."},{"step":4,"text":"Lower the heat to medium. Add the onion to the same skillet and cook 4 minutes until soft."},{"step":5,"text":"Stir in the garlic, ginger, garam masala, cumin, and paprika. Cook 1 minute until fragrant."},{"step":6,"text":"Pour in the tomato sauce and scrape up any browned bits. Simmer 3 minutes."},{"step":7,"text":"Return the chicken and its juices to the skillet. Simmer 6 minutes until the chicken reaches 165 F."},{"step":8,"text":"Stir in the cream and heat 2 minutes without boiling hard. Fluff the rice and serve the chicken and sauce over it."},{"step":9,"text":"For leftovers, cool within 2 hours and store the chicken and rice in airtight containers. Freeze up to 3 months, and reheat until steaming hot."}]'::jsonb, null, array['dinner', 'chicken', 'gluten_free', 'skillet', 'leftovers', 'freezer_friendly']::text[], 'indian', 'catalog', null),
  ('ec5de82b-0d21-5933-bd85-d8cc5a5ccfaa', null, 'One Pot Chickpea Spinach Curry', 'A one pot Indian-style curry of chickpeas and spinach in a spiced tomato and coconut sauce. It tastes warm, savory, and slightly sweet, and it is good the next day.', null, 'ai', null, 4, 10, 20, '[{"step":1,"text":"Heat the olive oil in a large pot over medium heat. Add the onion and cook 4 minutes, until soft and translucent."},{"step":2,"text":"Stir in the garlic and ginger. Cook 1 minute, until fragrant."},{"step":3,"text":"Add the cumin, coriander, turmeric, and garam masala. Stir for 30 seconds to toast the spices."},{"step":4,"text":"Pour in the diced tomatoes with their juice. Cook 3 minutes, stirring often, until the tomatoes break down and thicken slightly."},{"step":5,"text":"Add the chickpeas, coconut milk, water, salt, and pepper. Bring to a gentle boil, then lower the heat to medium-low."},{"step":6,"text":"Simmer uncovered for 10 minutes, stirring now and then, until the sauce is thick enough to coat a spoon."},{"step":7,"text":"Stir in the spinach a handful at a time. Cook 2 minutes, until the leaves are fully wilted."},{"step":8,"text":"Taste and add more salt if needed. Serve hot. Cool leftovers fully before storing in the fridge for 4 days or the freezer for 3 months."}]'::jsonb, null, array['dinner', 'beans', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot', 'pantry', 'leftovers', 'freezer_friendly']::text[], 'indian', 'catalog', null),
  ('db49d121-a3f4-5300-9265-ec0ace1aa48f', null, 'One Pot Beef and Kidney Bean Chili', 'A thick American chili with ground beef, kidney beans, and tomatoes. It tastes smoky and savory with a medium warmth, and it keeps well for days.', null, 'ai', null, 4, 15, 40, '[{"step":1,"text":"Heat the olive oil in a large heavy pot over medium-high heat for 1 minute."},{"step":2,"text":"Add the onion and bell pepper. Cook for 5 minutes, stirring often, until soft."},{"step":3,"text":"Stir in the garlic and cook for 30 seconds."},{"step":4,"text":"Add the ground beef. Cook for 8 minutes, breaking it up with a spoon, until no pink remains and it reaches 160 F."},{"step":5,"text":"Stir in the chili powder, cumin, smoked paprika, oregano, salt, and pepper. Cook for 1 minute until fragrant."},{"step":6,"text":"Add the crushed tomatoes, kidney beans, and water. Scrape up any browned bits from the bottom of the pot."},{"step":7,"text":"Bring to a boil, then reduce the heat to low. Simmer uncovered for 25 minutes, stirring now and then, until thick."},{"step":8,"text":"Taste and add more salt if needed. Cool leftovers fully before storing in airtight containers in the fridge or freezer."}]'::jsonb, null, array['dinner', 'beef', 'gluten_free', 'dairy_free', 'one_pot', 'pantry', 'leftovers', 'freezer_friendly']::text[], 'american', 'catalog', null),
  ('669ee434-d080-54e0-98a0-4540c07aacdb', null, 'One Pot Coconut Tomato Shrimp Curry', 'Shrimp simmered in a spiced coconut and tomato sauce over rice, all in one pot. It tastes rich, warm, and a little tangy.', null, 'ai', null, 4, 10, 20, '[{"step":1,"text":"Rinse the rice in a fine strainer until the water runs mostly clear. Cook it in a small pot with the water and a pinch of salt if you want rice on the side, or skip to the next step to use the rice in the curry pot."},{"step":2,"text":"Heat the coconut oil in a large deep skillet or Dutch oven over medium heat. Add the onion and cook for 4 minutes, until soft."},{"step":3,"text":"Stir in the garlic, ginger, curry powder, turmeric, and kosher salt. Cook for 1 minute, until fragrant."},{"step":4,"text":"Add the diced tomatoes with their juice and the coconut milk. Stir well and bring to a gentle simmer."},{"step":5,"text":"Simmer for 8 minutes, stirring now and then, until the sauce thickens slightly."},{"step":6,"text":"Add the shrimp in a single layer. Cover and cook for 4 to 5 minutes, until the shrimp are pink and curled and opaque in the center."},{"step":7,"text":"Stir in the cilantro. Spoon the curry over the cooked rice and serve hot."}]'::jsonb, null, array['dinner', 'shellfish', 'gluten_free', 'dairy_free', 'one_pot']::text[], 'indian', 'catalog', null),
  ('5d53f087-7db8-5bf9-8b1d-d748bbf2fbbc', null, 'Crispy Tofu and Vegetable Stir Fry with Ginger Soy Sauce', 'Cubes of pan-crisped tofu tossed with broccoli, red pepper, and carrots in a glossy ginger soy sauce. Savory and lightly sweet, served over steamed rice.', null, 'ai', null, 4, 15, 15, '[{"step":1,"text":"Bring 3 cups water and the rice to a boil in a medium pot. Cover, reduce to low, and cook 15 minutes until the water is absorbed. Keep covered off the heat."},{"step":2,"text":"Cut the tofu into 3/4 inch cubes and pat dry. Toss gently with 2 tbsp of the cornstarch and the salt."},{"step":3,"text":"Heat 3 tbsp oil in a large nonstick skillet over medium-high heat. Add the tofu in one layer and cook 8 minutes, turning, until golden and crisp on most sides. Move to a plate."},{"step":4,"text":"Whisk the soy sauce, maple syrup, rice vinegar, 1/2 cup water, and the remaining 1 tbsp cornstarch in a small bowl."},{"step":5,"text":"Add the remaining 1 tbsp oil to the skillet. Cook the broccoli, bell pepper, and carrots 4 minutes, stirring, until bright and just tender."},{"step":6,"text":"Add the garlic and ginger and stir 30 seconds until fragrant."},{"step":7,"text":"Stir the sauce and pour it into the skillet. Simmer 1 to 2 minutes until it thickens and coats the vegetables."},{"step":8,"text":"Return the tofu to the skillet and toss gently to coat. Serve over the rice."}]'::jsonb, null, array['dinner', 'tofu', 'vegetarian', 'vegan', 'dairy_free', 'skillet']::text[], 'chinese', 'catalog', null),
  ('6fa05def-d08c-5e66-9596-7da3377f3ac5', null, 'Pan Seared Cod Tacos with Lime Cabbage Slaw', 'Mild cod fillets seared in a skillet and tucked into warm corn tortillas with a crisp, tangy lime cabbage slaw. Gentle flavors with no heat.', null, 'ai', null, 4, 15, 10, '[{"step":1,"text":"Toss the cabbage and carrot with the lime juice, olive oil, 1/4 tsp salt, and honey in a large bowl. Set aside while you cook the fish."},{"step":2,"text":"Pat the cod dry with paper towels. Mix the cumin, paprika, garlic powder, 3/4 tsp salt, and pepper, then rub it over both sides of the fish."},{"step":3,"text":"Heat the avocado oil in a 12 inch nonstick skillet over medium-high heat until it shimmers."},{"step":4,"text":"Add the cod and cook 3 to 4 minutes, until the underside is golden and releases easily from the pan."},{"step":5,"text":"Flip the fish and cook 2 to 3 minutes more, until it flakes easily and reaches 145 F in the thickest part. Move it to a plate and break it into large chunks."},{"step":6,"text":"Wipe the skillet clean and warm it over medium heat. Heat the tortillas one or two at a time for about 30 seconds per side, until soft and lightly toasted."},{"step":7,"text":"Fill each tortilla with fish and top with slaw. Serve right away, 2 tacos per person."}]'::jsonb, null, array['dinner', 'fish', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly']::text[], 'mexican', 'catalog', null),
  ('a3e227cd-96d0-5b18-809d-f1d0e7b60d90', null, 'Ginger Garlic Pork Lettuce Cups', 'Ground pork cooked in a skillet with garlic, ginger, and crunchy water chestnuts. Spoon it into crisp lettuce cups for a savory, lightly sweet dinner.', null, 'ai', null, 4, 15, 10, '[{"step":1,"text":"Wash and dry the lettuce leaves. Stack them on a platter with the shredded carrot nearby."},{"step":2,"text":"Heat the oil in a 12-inch skillet over medium-high heat until it shimmers."},{"step":3,"text":"Add the pork and 1/2 tsp salt. Cook for 6 to 8 minutes, breaking it into small crumbles, until no pink remains and browned in spots."},{"step":4,"text":"Stir in the garlic, ginger, and the white parts of the green onions. Cook for 1 minute until fragrant."},{"step":5,"text":"Add the water chestnuts, coconut aminos, rice vinegar, and pepper. Cook for 2 minutes until the liquid reduces and coats the pork."},{"step":6,"text":"Check that the pork reads 160 F on an instant-read thermometer."},{"step":7,"text":"Spoon the pork into the lettuce cups. Top with the green onion tops and carrot, then serve right away."}]'::jsonb, null, array['dinner', 'pork', 'gluten_free', 'dairy_free', 'skillet']::text[], 'chinese', 'catalog', null),
  ('fd3f1fb6-9f26-5a66-9b00-1862489c5915', null, 'Spanish Garlic Shrimp with Lemon Rice', 'Shrimp sizzled in olive oil with plenty of garlic, smoked paprika, and a little chili, finished with lemon and parsley. Served over fluffy white rice.', null, 'ai', null, 4, 10, 10, '[{"step":1,"text":"Warm the cooked rice in a covered microwave-safe bowl for 2 minutes, or until steaming hot. Stir in the lemon zest and keep covered."},{"step":2,"text":"Pat the shrimp dry with paper towels. Toss them with the salt, pepper, and smoked paprika."},{"step":3,"text":"Heat the olive oil in a 12-inch skillet over medium heat. Add the garlic and red pepper flakes and cook for 1 minute, until the garlic is fragrant and just pale gold."},{"step":4,"text":"Raise the heat to medium-high and add the shrimp in a single layer. Cook for 2 minutes without moving them, until the undersides turn pink."},{"step":5,"text":"Flip the shrimp and cook for 1 to 2 minutes more, until they are pink and opaque and curl into a loose C shape."},{"step":6,"text":"Pour in the white wine and cook for 1 minute, scraping up any browned bits, until the sauce is slightly reduced."},{"step":7,"text":"Remove the skillet from the heat. Squeeze in the juice of 2 lemon wedges and stir in the parsley."},{"step":8,"text":"Divide the rice among four plates and spoon the shrimp and garlic oil over the top. Serve with the remaining lemon wedges."}]'::jsonb, null, array['dinner', 'shellfish', 'gluten_free', 'dairy_free', 'skillet']::text[], 'spanish', 'catalog', null)
insert into public.recipes (id, household_id, title, description, image_url, source_type, source_url, servings, prep_min, cook_min, instructions, nutrition, tags, cuisine, visibility, created_by)
values
  ('05fc7dc0-7964-5cb6-922f-8081773def1a', null, 'Grilled Flank Steak with Corn and Zucchini', 'Flank steak grilled with sweet charred corn and zucchini. The steak has a simple garlic, paprika, and cumin crust with a squeeze of lime.', null, 'ai', null, 4, 15, 18, '[{"step":1,"text":"Mix 1 tbsp olive oil, the garlic, paprika, cumin, 1 tsp salt, and the pepper in a small bowl. Rub it all over the flank steak and let it sit while the grill heats."},{"step":2,"text":"Heat an outdoor grill or grill pan to medium-high, about 450 F. Brush the grates lightly with oil if needed."},{"step":3,"text":"Brush the corn and zucchini with the remaining 2 tbsp oil. Sprinkle the vegetables with the remaining 1/2 tsp salt."},{"step":4,"text":"Grill the corn for 10 to 12 minutes, turning every 3 minutes, until browned in spots and tender."},{"step":5,"text":"Grill the steak for 4 to 6 minutes per side. Cook until a thermometer in the thickest part reads 145 F."},{"step":6,"text":"Grill the zucchini cut side down for 3 to 4 minutes per side, until tender with dark grill marks."},{"step":7,"text":"Rest the steak on a board for 5 minutes. Slice it thinly across the grain."},{"step":8,"text":"Serve the steak with the corn and zucchini and squeeze lime wedges over everything."}]'::jsonb, null, array['dinner', 'beef', 'gluten_free', 'dairy_free', 'grill']::text[], 'american', 'catalog', null),
  ('b99e43f9-8ddc-54e0-b207-2fee1b269b09', null, 'Huevos Rancheros on Corn Tortillas', 'Crisp corn tortillas topped with warm black beans, fried eggs, and a mild tomato salsa. Soft, savory, and gentle, with no heat.', null, 'ai', null, 4, 10, 15, '[{"step":1,"text":"Heat 1 tbsp oil in a 12 inch nonstick skillet over medium heat. Add the onion and cook 3 minutes, until soft."},{"step":2,"text":"Stir in the garlic and cumin and cook 30 seconds. Add the diced tomatoes with their juice and 1/4 tsp salt, and simmer 5 minutes until slightly thickened. Spoon this salsa into a bowl and wipe the skillet clean."},{"step":3,"text":"Mash about a third of the black beans with a fork in a small bowl, then stir in the rest of the beans."},{"step":4,"text":"Warm the beans in a small saucepan over low heat for 3 minutes, stirring now and then."},{"step":5,"text":"Heat 1 tbsp oil in the skillet over medium heat. Warm the tortillas 4 at a time for 30 seconds per side until soft and lightly crisp at the edges, adding a little oil as needed, and stack on a plate under foil."},{"step":6,"text":"Add the remaining oil to the skillet over medium-low heat. Crack in the eggs and cook 3 to 4 minutes, until the whites are fully set and the yolks are as firm as you like."},{"step":7,"text":"Season the eggs with the remaining salt and the pepper."},{"step":8,"text":"Spread beans on each tortilla, top with an egg, spoon on the salsa, and sprinkle with cheese. Serve 2 tortillas per person right away."}]'::jsonb, null, array['dinner', 'eggs', 'vegetarian', 'gluten_free', 'skillet', 'kid_friendly']::text[], 'mexican', 'catalog', null),
  ('409aa914-e1eb-5645-9b6f-0edd59cd01cd', null, 'Beef Bulgogi Rice Bowls', 'Ground beef cooked in a mild, sweet garlic and ginger sauce, served over rice with fresh cucumber and carrots. No heat and no sesame.', null, 'ai', null, 4, 10, 15, '[{"step":1,"text":"Combine the rice, water, and 1/2 tsp salt in a medium saucepan. Bring to a boil, then cover and reduce the heat to low."},{"step":2,"text":"Cook the rice for 15 minutes, until the water is absorbed and the grains are tender. Keep it covered off the heat until serving."},{"step":3,"text":"Heat the oil in a 12 inch skillet over medium-high heat. Add the ground beef and break it into small crumbles."},{"step":4,"text":"Cook for 6 to 7 minutes, stirring now and then, until no pink remains and the beef reaches 160 F."},{"step":5,"text":"Add the garlic and ground ginger. Stir for 30 seconds, until fragrant."},{"step":6,"text":"Stir in the coconut aminos, maple syrup, and pepper. Simmer for 2 to 3 minutes, until the sauce thickens and coats the beef."},{"step":7,"text":"Fluff the rice and divide it among 4 bowls. Spoon the beef over the rice."},{"step":8,"text":"Top each bowl with cucumber, grated carrots, and scallions. Serve warm."}]'::jsonb, null, array['dinner', 'beef', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly']::text[], 'korean', 'catalog', null),
  ('ced90280-e50d-5cc9-b8c6-ad68a8873e75', null, 'Grilled Lamb Kofta with Lemon Herb Sauce', 'Spiced ground lamb skewers grilled until browned, served over rice with cucumber and a bright lemon herb sauce. The meat is warmly spiced and the sauce is fresh and tart.', null, 'ai', null, 4, 20, 15, '[{"step":1,"text":"Bring the rice, water, and 1/2 tsp of the kosher salt from the kofta amount to a boil in a medium pot. Cover, reduce to low, and cook 15 minutes until the water is absorbed."},{"step":2,"text":"Heat a grill or grill pan to medium-high, about 450 F. Brush the grates with a little oil."},{"step":3,"text":"In a large bowl, mix the lamb, onion, garlic, parsley, cumin, coriander, cinnamon, remaining salt, and pepper. Mix gently until just combined."},{"step":4,"text":"Divide the meat into 8 portions. Shape each into a 4-inch log about 1 inch thick, pressing firmly so it holds together."},{"step":5,"text":"Brush the kofta with 1 tbsp olive oil. Grill 10 to 12 minutes, turning every 3 minutes, until browned and a thermometer reads 160 F."},{"step":6,"text":"While the kofta cook, stir 1/4 cup olive oil, the lemon juice, and the mint together in a small bowl for the sauce."},{"step":7,"text":"Fluff the rice with a fork. Divide it among four plates and top with the kofta and cucumber slices."},{"step":8,"text":"Spoon the lemon herb sauce over the kofta and rice. Serve right away."}]'::jsonb, null, array['dinner', 'lamb', 'gluten_free', 'dairy_free', 'grill']::text[], 'middle eastern', 'catalog', null),
  ('afbbd0c8-6ef0-56c1-97f8-59072fb09baa', null, 'Lentil and Mushroom Bolognese with Spaghetti', 'A thick, savory lentil and mushroom sauce simmered in one skillet and spooned over gluten-free spaghetti. It tastes rich and tomato-forward, and it freezes well.', null, 'ai', null, 4, 15, 25, '[{"step":1,"text":"Bring a large pot of salted water to a boil for the spaghetti. Cook the spaghetti 1 minute less than the package time, until just tender."},{"step":2,"text":"While the water heats, warm the olive oil in a deep 12-inch skillet over medium heat. Add the onion and carrots and cook 5 minutes, until soft."},{"step":3,"text":"Add the mushrooms and cook 6 to 8 minutes, stirring often, until the liquid cooks off and they brown."},{"step":4,"text":"Stir in the garlic, oregano, and basil. Cook 1 minute, until fragrant."},{"step":5,"text":"Add the crushed tomatoes, lentils, water, salt, and pepper. Stir well."},{"step":6,"text":"Simmer over medium-low heat for 12 minutes, stirring now and then, until the sauce is thick and clings to a spoon."},{"step":7,"text":"Drain the spaghetti and toss it with half of the sauce, or serve the sauce on top."},{"step":8,"text":"To freeze, cool the sauce completely and store it in airtight containers for up to 3 months. Reheat in a skillet over medium heat with a splash of water until hot."}]'::jsonb, null, array['dinner', 'lentils', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'skillet', 'freezer_friendly']::text[], 'italian', 'catalog', null),
  ('66db4ec4-6fa3-54bc-a49a-f814468aca80', null, 'Maple Glazed Tempeh with Sweet Potatoes and Kale', 'Sheet pan tempeh glazed with maple and mustard, served over roasted sweet potatoes and crisp kale. Sweet, tangy, and lightly smoky.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Heat the oven to 425 F. Line a large rimmed sheet pan with parchment."},{"step":2,"text":"Toss the sweet potatoes with 2 tbsp olive oil, 1/2 tsp salt, and the smoked paprika. Spread them over half of the pan."},{"step":3,"text":"Roast the sweet potatoes for 10 minutes while you make the glaze."},{"step":4,"text":"Whisk the maple syrup, tamari, vinegar, mustard, and garlic in a bowl. Add the tempeh slabs and turn to coat."},{"step":5,"text":"Toss the kale with 1 tbsp olive oil, the remaining 1/2 tsp salt, and the pepper in a large bowl."},{"step":6,"text":"Pull the pan out. Stir the sweet potatoes and lay the tempeh on the empty half. Spoon the leftover glaze over the tempeh."},{"step":7,"text":"Roast for 10 minutes. Flip the tempeh and scatter the kale over the pan, then drizzle it with the last 1 tbsp olive oil."},{"step":8,"text":"Roast 5 to 8 minutes more, until the sweet potatoes are tender, the kale edges are crisp, and the tempeh is browned and sticky."},{"step":9,"text":"Serve the tempeh over the sweet potatoes and kale."}]'::jsonb, null, array['dinner', 'tempeh', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'sheet_pan']::text[], 'american', 'catalog', null),
  ('cf8eebb5-35c9-5f9a-9637-f98ab7384c9d', null, 'Margherita Flatbread Pizzas', 'Crisp flatbreads topped with mild tomato sauce, melted fresh mozzarella, and torn basil. Simple, cheesy, and easy for kids to top themselves.', null, 'ai', null, 4, 10, 12, '[{"step":1,"text":"Heat the oven to 450 F. Line two rimmed baking sheets with parchment paper."},{"step":2,"text":"Stir the tomato sauce, 1 tbsp olive oil, oregano, garlic powder, sugar, and salt in a bowl."},{"step":3,"text":"Place two flatbreads on each baking sheet. Spread about 1/4 cup sauce on each, leaving a thin border."},{"step":4,"text":"Pat the mozzarella slices dry with a paper towel. Lay them over the sauce, dividing evenly."},{"step":5,"text":"Bake for 10 to 12 minutes, swapping the pans halfway through. The cheese should be melted and the edges golden brown."},{"step":6,"text":"Brush the edges with the remaining 1 tbsp olive oil. Tear the basil over the top."},{"step":7,"text":"Let the pizzas cool for 2 minutes, then slice each into wedges and serve."}]'::jsonb, null, array['dinner', 'cheese', 'vegetarian', 'bake', 'kid_friendly']::text[], 'italian', 'catalog', null),
  ('bd3899c3-b8a9-5137-9d99-b91a591a0544', null, 'Greek Chickpea Salad Bowls', 'A cold chickpea salad with cucumber, tomato, olives, and red onion in a bright lemon and oregano dressing. It is tangy, salty, and fresh.', null, 'ai', null, 4, 15, 0, '[{"step":1,"text":"Rinse the chickpeas well and shake off the water. Put them in a large bowl."},{"step":2,"text":"Add the cucumber, tomatoes, red onion, and olives to the bowl."},{"step":3,"text":"In a small bowl, whisk the olive oil, lemon juice, oregano, garlic, salt, and pepper until smooth."},{"step":4,"text":"Pour the dressing over the salad. Toss until every piece is coated."},{"step":5,"text":"Let the salad sit for 5 minutes so the onion softens and the flavors blend."},{"step":6,"text":"Taste and add more salt or lemon juice if needed. Divide among 4 bowls."}]'::jsonb, null, array['dinner', 'beans', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'no_cook', 'pantry']::text[], 'greek', 'catalog', null),
  ('f85e003b-2502-533d-9525-c39e12f1192b', null, 'Mediterranean Lentil Soup with Lemon', 'A hearty one pot soup of brown lentils, carrots, and celery with cumin and oregano. A squeeze of lemon at the end makes it bright and savory.', null, 'ai', null, 4, 9, 26, '[{"step":1,"text":"Heat the olive oil in a 5 quart pot over medium-high heat."},{"step":2,"text":"Add the onion, carrots, and celery. Cook 4 minutes, stirring often, until the onion looks soft and shiny."},{"step":3,"text":"Stir in the cumin, garlic powder, and oregano. Cook 30 seconds until fragrant."},{"step":4,"text":"Add the diced tomatoes with their juice, the lentils, the water, and the salt."},{"step":5,"text":"Bring to a boil over high heat. Reduce to a steady simmer and partly cover."},{"step":6,"text":"Simmer 18 to 20 minutes, stirring now and then, until the lentils and carrots are tender."},{"step":7,"text":"Stir in the pepper and lemon juice. Taste and add a pinch more salt if needed."},{"step":8,"text":"Ladle into bowls. Cool leftovers fully before storing in the fridge or freezer, and add a little water when reheating."}]'::jsonb, null, array['dinner', 'lentils', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot', 'pantry', 'leftovers', 'freezer_friendly']::text[], 'mediterranean', 'catalog', null),
  ('cd6d5a59-b7a4-5274-9f64-235f8b0f9356', null, 'Baked Miso Salmon with Rice and Green Beans', 'Salmon fillets baked with a salty-sweet miso glaze, served over steamed rice with tender green beans. The glaze is savory with a little sweetness.', null, 'ai', null, 4, 10, 15, '[{"step":1,"text":"Heat the oven to 425 F. Line a rimmed baking sheet with parchment paper."},{"step":2,"text":"Combine the rice and water in a medium pot with a lid. Bring to a boil, cover, and reduce the heat to low. Cook 15 minutes until the water is absorbed."},{"step":3,"text":"Whisk the miso, honey, rice vinegar, soy sauce, and ginger in a small bowl until smooth."},{"step":4,"text":"Toss the green beans with the oil and salt. Spread them along one side of the baking sheet."},{"step":5,"text":"Place the salmon on the other side of the pan. Spread the glaze over the top of each fillet."},{"step":6,"text":"Bake 12 to 15 minutes. The salmon is done when it reaches 145 F and flakes easily, and the beans are tender with browned spots."},{"step":7,"text":"Fluff the rice with a fork. Divide the rice among four plates and top with salmon and green beans."},{"step":8,"text":"Spoon any glaze from the pan over the fish and sprinkle with the scallions."}]'::jsonb, null, array['dinner', 'fish', 'dairy_free', 'bake']::text[], 'japanese', 'catalog', null),
  ('77543c70-8dd4-50b6-9fc2-04458d4229cf', null, 'Moroccan Lamb and Chickpea Stew', 'A one pot stew of tender lamb, chickpeas, and carrots in a warm tomato sauce with cumin, cinnamon, and ginger. It is savory and lightly sweet, and it tastes better the next day.', null, 'ai', null, 4, 20, 70, '[{"step":1,"text":"Heat the oil in a large Dutch oven over medium-high heat. Pat the lamb dry and season it with the salt and pepper."},{"step":2,"text":"Brown the lamb in the pot in two batches, about 5 minutes per batch. Move the browned lamb to a plate."},{"step":3,"text":"Lower the heat to medium. Add the onion and cook for 5 minutes, until soft."},{"step":4,"text":"Stir in the garlic, cumin, ginger, cinnamon, and paprika. Cook for 30 seconds until fragrant."},{"step":5,"text":"Add the tomatoes, water, and the lamb with any juices. Scrape up the browned bits from the bottom of the pot."},{"step":6,"text":"Bring to a boil, then cover and reduce to low. Simmer for 35 minutes."},{"step":7,"text":"Stir in the carrots and chickpeas. Cover and simmer for 20 to 25 minutes, until the carrots are tender and the lamb is easily pierced with a fork."},{"step":8,"text":"Stir in the cilantro. Taste and add more salt if needed. Cool leftovers fully before storing in the fridge for 4 days or the freezer for 3 months."}]'::jsonb, null, array['dinner', 'lamb', 'gluten_free', 'dairy_free', 'one_pot', 'leftovers', 'freezer_friendly']::text[], 'moroccan', 'catalog', null),
  ('65bcc139-71df-5c53-ba5c-e6bc0995a4ae', null, 'Creamy Mushroom Stroganoff with Egg Noodles', 'Tender mushrooms and onion in a mild sour cream sauce, served over egg noodles. It tastes savory, creamy, and gently tangy with no heat.', null, 'ai', null, 4, 10, 25, '[{"step":1,"text":"Bring a large pot of water to a boil and stir in 1 tbsp salt. Cook the egg noodles for 6 to 8 minutes until tender, then drain."},{"step":2,"text":"Heat the butter and olive oil in a 12 inch skillet over medium-high heat. Add the mushrooms in one layer and cook for 8 minutes, stirring now and then, until browned and the liquid is gone."},{"step":3,"text":"Lower the heat to medium. Add the onion and cook for 4 minutes until soft."},{"step":4,"text":"Stir in the garlic and cook for 30 seconds. Sprinkle the flour over the vegetables and stir for 1 minute."},{"step":5,"text":"Slowly pour in the vegetable broth, stirring to scrape up the browned bits. Add the paprika, 1/2 tsp salt, and pepper."},{"step":6,"text":"Simmer for 5 minutes until the sauce coats the back of a spoon."},{"step":7,"text":"Turn the heat to low and stir in the sour cream. Warm for 1 minute without boiling, so the sauce stays smooth."},{"step":8,"text":"Serve the stroganoff over the egg noodles and top with parsley."}]'::jsonb, null, array['dinner', 'vegetables', 'vegetarian', 'skillet', 'kid_friendly']::text[], 'eastern european', 'catalog', null),
  ('9f06a4ee-0e3a-51a4-a04e-050243623d31', null, 'Dijon Roasted Pork Tenderloin with Sweet Potatoes', 'Pork tenderloin coated in a tangy Dijon and herb rub, roasted on one pan with sweet potatoes and broccoli. The pork is juicy and the vegetables are lightly browned.', null, 'ai', null, 4, 15, 30, '[{"step":1,"text":"Heat the oven to 425 F. Line a large rimmed sheet pan with parchment paper."},{"step":2,"text":"Toss the sweet potatoes with 2 tbsp olive oil, 1/2 tsp salt, and 1/8 tsp pepper on the pan. Spread them out and roast for 10 minutes."},{"step":3,"text":"Mix the Dijon, garlic, thyme, 1 tbsp olive oil, 1 tsp salt, and 1/2 tsp pepper in a small bowl. Pat the pork dry and rub the mixture all over it."},{"step":4,"text":"Toss the broccoli with 1 tbsp olive oil, 1/4 tsp salt, and 1/8 tsp pepper in the bowl you used for the potatoes."},{"step":5,"text":"Pull the pan from the oven. Push the potatoes to the sides and set the pork in the center. Scatter the broccoli around the pork."},{"step":6,"text":"Roast for 18 to 22 minutes, until the pork reads 145 F in the thickest part and the potatoes are tender and browned at the edges."},{"step":7,"text":"Rest the pork on a cutting board for 5 minutes. Slice it into 1/2 inch rounds and serve with the vegetables."}]'::jsonb, null, array['dinner', 'pork', 'gluten_free', 'dairy_free', 'sheet_pan']::text[], 'french', 'catalog', null),
  ('ade12034-4dec-5af1-855a-3d6efb452afc', null, 'One Pot Chicken and Rice with Peas and Carrots', 'Tender chicken, rice, carrots, and peas cooked together in one pot. It tastes mild and savory, and it reheats well the next day.', null, 'ai', null, 4, 10, 25, '[{"step":1,"text":"Heat the olive oil in a large pot or deep skillet with a lid over medium-high heat. Add the chicken, salt, pepper, and thyme. Cook 4 minutes, stirring, until lightly browned on the outside."},{"step":2,"text":"Add the onion and carrots. Cook 3 minutes, until the onion softens."},{"step":3,"text":"Stir in the garlic and rice. Cook 1 minute, stirring, so the rice is coated."},{"step":4,"text":"Pour in the water and scrape up any browned bits from the bottom. Bring to a boil."},{"step":5,"text":"Reduce the heat to low and cover. Cook 15 minutes, without lifting the lid, until the rice is tender and the water is absorbed."},{"step":6,"text":"Scatter the peas over the rice, cover, and let stand off the heat for 5 minutes."},{"step":7,"text":"Check that the chicken reads 165 F in the thickest piece. Fluff with a fork and serve."}]'::jsonb, null, array['dinner', 'chicken', 'gluten_free', 'dairy_free', 'one_pot', 'kid_friendly', 'leftovers']::text[], 'american', 'catalog', null),
  ('2b463421-02b3-5fc6-afdd-4102802522bb', null, 'One Pot Pasta e Fagioli', 'A thick Italian-style soup of cannellini beans, tomatoes, and small gluten-free pasta. It tastes mild, savory, and herby, and it is even better the next day.', null, 'ai', null, 4, 10, 25, '[{"step":1,"text":"Heat the olive oil in a large pot over medium heat. Add the onion and carrots and cook for 6 minutes, stirring often, until soft."},{"step":2,"text":"Stir in the garlic and cook for 1 minute until fragrant."},{"step":3,"text":"Add the diced tomatoes with their juice, the beans, the broth, the Italian seasoning, the salt, and the pepper. Bring to a boil."},{"step":4,"text":"Mash about 1/2 cup of the beans against the side of the pot with a spoon. This thickens the soup."},{"step":5,"text":"Stir in the pasta. Reduce to a steady simmer and cook for 10 to 12 minutes, stirring often, until the pasta is tender."},{"step":6,"text":"Taste and add a pinch more salt if needed. The soup should be thick; if it is too thick, stir in a splash of water."},{"step":7,"text":"Rest for 5 minutes before serving. The pasta will keep absorbing liquid, so add a little water when reheating leftovers."}]'::jsonb, null, array['dinner', 'beans', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot', 'kid_friendly', 'pantry', 'leftovers']::text[], 'italian', 'catalog', null),
  ('47637680-4075-5536-a161-649cb7396a63', null, 'Skillet Pork Chops with Apples and Onions', 'Pork chops seared in a skillet and served with soft sweet apples and onions in a light pan sauce. The flavor is mild, savory, and slightly sweet.', null, 'ai', null, 4, 10, 20, '[{"step":1,"text":"Pat the pork chops dry. Season both sides with the salt, pepper, and thyme."},{"step":2,"text":"Heat the olive oil in a 12 inch skillet over medium-high heat until it shimmers."},{"step":3,"text":"Sear the chops for 4 minutes per side until deep golden. Move them to a plate."},{"step":4,"text":"Lower the heat to medium. Add the onion to the skillet and cook for 4 minutes, stirring, until soft."},{"step":5,"text":"Add the apples and maple syrup. Cook for 3 minutes until the apples start to soften."},{"step":6,"text":"Pour in the apple juice and vinegar. Scrape up the browned bits and simmer for 2 minutes."},{"step":7,"text":"Return the chops and any juices to the skillet. Cook for 3 to 4 minutes, spooning the apples over the top, until the pork reads 145 F in the thickest part."},{"step":8,"text":"Rest the chops for 3 minutes. Serve with the apples, onions, and pan sauce spooned over."}]'::jsonb, null, array['dinner', 'pork', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly']::text[], 'american', 'catalog', null),
  ('9d1965e6-a0ee-50d3-8a0a-888846933de0', null, 'Pressure Cooker Beef Stew', 'A thick beef stew with tender chuck, potatoes, and carrots in a savory tomato and herb gravy. It reheats well and tastes even better the next day.', null, 'ai', null, 4, 20, 50, '[{"step":1,"text":"Pat the beef dry and toss it with the salt and pepper."},{"step":2,"text":"Set the electric pressure cooker to saute on high and add the oil. Brown the beef in two batches for about 4 minutes per batch, until deep brown on the outside. Move it to a plate."},{"step":3,"text":"Add the onion to the pot and cook for 3 minutes, until soft. Stir in the garlic and tomato paste and cook for 1 minute."},{"step":4,"text":"Pour in the broth and scrape up any browned bits from the bottom of the pot. Add the thyme, bay leaves, and beef."},{"step":5,"text":"Lock the lid and set the valve to sealing. Cook on high pressure for 25 minutes."},{"step":6,"text":"Let the pressure release naturally for 10 minutes, then turn the valve to venting. Open the lid and add the potatoes and carrots."},{"step":7,"text":"Lock the lid again and cook on high pressure for 5 minutes. Quick release the pressure and check that the potatoes are fork tender and the beef is soft."},{"step":8,"text":"Remove the bay leaves. Stir the cornstarch and water in a small bowl until smooth."},{"step":9,"text":"Set the pot to saute and stir in the cornstarch mixture. Simmer for 2 minutes, until the stew coats the back of a spoon."},{"step":10,"text":"Cool leftovers for 30 minutes, then store in airtight containers. Refrigerate up to 4 days or freeze up to 3 months."}]'::jsonb, null, array['dinner', 'beef', 'gluten_free', 'dairy_free', 'pressure_cooker', 'leftovers', 'freezer_friendly']::text[], 'american', 'catalog', null),
  ('c44d6275-c418-5fa1-8784-6adf65f3a184', null, 'Pressure Cooker Pork Carnitas Tacos', 'Tender pork shoulder cooked with orange, lime, and warm spices, then crisped under the broiler. Served in warm corn tortillas with onion and cilantro.', null, 'ai', null, 4, 20, 60, '[{"step":1,"text":"Toss the pork with the salt, pepper, cumin, and oregano in a large bowl. Let it sit while you prep the rest."},{"step":2,"text":"Set a 6 quart electric pressure cooker to saute on high. Add the olive oil and heat for 2 minutes."},{"step":3,"text":"Brown the pork in two batches, about 3 minutes per side, until deeply golden. Move each batch to a plate."},{"step":4,"text":"Pour the orange juice and lime juice into the pot. Scrape up the browned bits from the bottom."},{"step":5,"text":"Return the pork to the pot. Add the yellow onion wedges and garlic."},{"step":6,"text":"Lock the lid and seal the vent. Cook on high pressure for 40 minutes, then let the pressure release naturally for 10 minutes before opening the vent."},{"step":7,"text":"Heat the oven broiler to high. Shred the pork with two forks. It should fall apart with no resistance."},{"step":8,"text":"Spread the pork on a rimmed baking sheet and spoon over 1/2 cup of the cooking liquid. Broil 4 to 5 minutes until the edges are browned and crisp."},{"step":9,"text":"Warm the tortillas in a dry skillet over medium heat, about 30 seconds per side. Fill with pork, diced white onion, and cilantro."},{"step":10,"text":"Cool leftover pork in its juices. Refrigerate up to 4 days or freeze up to 3 months, then reheat in a skillet until steaming hot."}]'::jsonb, null, array['dinner', 'pork', 'gluten_free', 'dairy_free', 'pressure_cooker', 'leftovers', 'freezer_friendly']::text[], 'mexican', 'catalog', null),
  ('88499565-9cda-5dac-98fd-9bb7db3982e2', null, 'One Pot Ratatouille over Soft Polenta', 'A French vegetable stew of eggplant, zucchini, peppers, and tomatoes, simmered with garlic and thyme. It is served over creamy polenta and tastes sweet, herby, and rich.', null, 'ai', null, 4, 20, 35, '[{"step":1,"text":"Heat 2 tbsp olive oil in a large Dutch oven or deep 12 inch skillet over medium-high heat. Add the onion and cook 4 minutes, until soft."},{"step":2,"text":"Stir in the garlic and eggplant. Cook 6 to 8 minutes, stirring often, until the eggplant starts to brown at the edges."},{"step":3,"text":"Add the bell pepper and zucchini. Cook 3 minutes."},{"step":4,"text":"Pour in the diced tomatoes with their juice. Add the thyme, 1 tsp salt, and the pepper, and stir well."},{"step":5,"text":"Reduce heat to medium-low, cover partly, and simmer 20 minutes. The vegetables should be very tender and the sauce thick."},{"step":6,"text":"While the stew simmers, bring the water and 1 tsp salt to a boil in a medium pot. Slowly whisk in the cornmeal in a thin stream."},{"step":7,"text":"Lower heat to low and cook 20 to 25 minutes, stirring every few minutes, until the polenta is thick and creamy and pulls away from the pot."},{"step":8,"text":"Taste the ratatouille and add more salt if needed. Spoon the polenta into four bowls and top with the ratatouille."}]'::jsonb, null, array['dinner', 'vegetables', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot']::text[], 'french', 'catalog', null),
  ('60c99ec5-8cac-5d49-8d1b-621b55f0fe02', null, 'Cajun Red Beans and Rice', 'A one pot dish of red kidney beans and long grain rice with bell pepper, celery, and onion. It tastes smoky and savory with mild cayenne heat.', null, 'ai', null, 4, 15, 35, '[{"step":1,"text":"Heat the olive oil in a large pot or deep skillet over medium heat. Add the onion, bell pepper, and celery."},{"step":2,"text":"Cook for 6 to 8 minutes, stirring often, until the vegetables are soft and the onion is translucent."},{"step":3,"text":"Add the garlic, smoked paprika, thyme, and cayenne. Stir for 1 minute until fragrant."},{"step":4,"text":"Add the kidney beans, rice, water, salt, black pepper, and bay leaves. Stir well and scrape up any bits from the bottom of the pot."},{"step":5,"text":"Bring to a boil over high heat. Reduce to low and cover tightly."},{"step":6,"text":"Simmer for 18 to 20 minutes without lifting the lid, until the rice is tender and the water is absorbed."},{"step":7,"text":"Remove from the heat and let stand covered for 5 minutes. Discard the bay leaves."},{"step":8,"text":"Mash a few beans against the side of the pot with a spoon to thicken it. Fluff with a fork and serve."}]'::jsonb, null, array['dinner', 'beans', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot', 'pantry', 'leftovers']::text[], 'cajun', 'catalog', null)
insert into public.recipes (id, household_id, title, description, image_url, source_type, source_url, servings, prep_min, cook_min, instructions, nutrition, tags, cuisine, visibility, created_by)
values
  ('a5ec8a39-b075-5535-b0dd-87b531961167', null, 'Ginger Turmeric Red Lentil Dal', 'A thick, soft red lentil stew with ginger, garlic, and turmeric, cooked in one pot with basmati rice. It tastes warm and earthy with a little tang from lemon.', null, 'ai', null, 4, 10, 25, '[{"step":1,"text":"Rinse the rice in a fine strainer until the water runs mostly clear. Set it aside to drain."},{"step":2,"text":"Heat the oil in a large pot over medium heat. Add the onion and cook for 5 minutes, until soft and lightly golden."},{"step":3,"text":"Stir in the garlic, ginger, turmeric, and cumin. Cook for 1 minute, until fragrant."},{"step":4,"text":"Add the lentils, tomatoes with their juice, 4 cups of the water, and the salt. Bring to a boil, then lower the heat to a simmer."},{"step":5,"text":"Simmer uncovered for 18 to 20 minutes, stirring often, until the lentils fall apart and the dal is thick. Add a splash of water if it gets too thick."},{"step":6,"text":"While the dal cooks, combine the rice and the remaining 1 cup water... in a separate covered saucepan is not needed: instead, stir the drained rice into the dal after 8 minutes of simmering, add 1 more cup of water if the pot looks dry, and keep simmering."},{"step":7,"text":"Cook until the rice is tender and the lentils are creamy, about 12 more minutes. Stir often so nothing sticks to the bottom."},{"step":8,"text":"Stir in the lemon juice and taste for salt. Rest the pot off the heat for 5 minutes, then serve."}]'::jsonb, null, array['dinner', 'lentils', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot', 'pantry', 'leftovers', 'freezer_friendly']::text[], 'indian', 'catalog', null),
  ('54da95cf-de5e-5d04-b5be-f74b60bfd2cd', null, 'Spiced Tomato Pepper Poached Eggs', 'Eggs poached in a thick sauce of tomatoes and roasted red peppers. The sauce is warm and smoky with cumin and paprika. Serve it with rice.', null, 'ai', null, 4, 10, 20, '[{"step":1,"text":"Heat the olive oil in a 12-inch skillet with a lid over medium heat. Add the onion and cook for 5 minutes, until soft."},{"step":2,"text":"Stir in the garlic, cumin, paprika, coriander, and cayenne. Cook for 1 minute, until fragrant."},{"step":3,"text":"Add the crushed tomatoes, roasted red peppers, salt, and black pepper. Simmer for 10 minutes, stirring now and then, until the sauce is thick."},{"step":4,"text":"Make 8 small wells in the sauce with the back of a spoon. Crack an egg into each well."},{"step":5,"text":"Cover the skillet and cook on low heat for 4 to 6 minutes. The whites should be set and the yolks still soft."},{"step":6,"text":"Spoon the warm rice into four bowls. Top each with 2 eggs and plenty of sauce."}]'::jsonb, null, array['dinner', 'eggs', 'vegetarian', 'gluten_free', 'dairy_free', 'skillet', 'pantry']::text[], 'middle eastern', 'catalog', null),
  ('0cdcd1ff-3528-53bb-8025-49f868427d08', null, 'Sheet Pan Chicken Shawarma with Rice and Cucumber', 'Chicken thighs roasted with red onion and bell peppers in warm spices, served over rice with fresh cucumber. Savory, garlicky, and lightly tangy with lemon.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Heat the oven to 450 F. Line a large rimmed sheet pan with parchment."},{"step":2,"text":"Combine the rice and water in a medium pot with a lid. Bring to a boil, cover, and reduce to low. Cook 15 to 18 minutes until the water is absorbed."},{"step":3,"text":"In a large bowl, stir the olive oil, garlic, lemon juice, cumin, paprika, coriander, cinnamon, turmeric, salt, and pepper."},{"step":4,"text":"Add the chicken, onion, and bell peppers to the bowl. Toss until everything is coated."},{"step":5,"text":"Spread the mixture in a single layer on the sheet pan. Leave a little space between the pieces."},{"step":6,"text":"Roast 18 to 20 minutes, stirring once halfway, until the chicken reaches 165 F and the edges of the onion and peppers are browned."},{"step":7,"text":"Fluff the rice with a fork. Divide it among four plates."},{"step":8,"text":"Top the rice with the chicken and vegetables and scatter the cucumber on the side. Store leftovers in separate containers so the cucumber stays crisp."}]'::jsonb, null, array['dinner', 'chicken', 'gluten_free', 'dairy_free', 'sheet_pan', 'leftovers']::text[], 'middle eastern', 'catalog', null),
  ('4d1fb791-5f12-5661-b954-93fbffd2fbaa', null, 'Sheet Pan Lemon Garlic Chicken Thighs', 'Boneless chicken thighs roasted with baby potatoes and green beans on one pan. The flavor is mild, with bright lemon and soft roasted garlic.', null, 'ai', null, 4, 15, 35, '[{"step":1,"text":"Heat the oven to 425 F. Line a large rimmed baking sheet with parchment paper."},{"step":2,"text":"Toss the potatoes on the pan with 1 tbsp olive oil, 1/4 tsp salt, and 1/4 tsp pepper. Spread them cut side down and roast for 10 minutes."},{"step":3,"text":"Stir together the remaining 3 tbsp olive oil, garlic, lemon zest, lemon juice, oregano, paprika, 1 tsp salt, and 1/4 tsp pepper in a large bowl."},{"step":4,"text":"Add the chicken to the bowl and turn it to coat well. Toss the green beans in the same bowl to pick up the leftover marinade."},{"step":5,"text":"Move the potatoes to one side of the pan. Place the chicken in a single layer in the center and scatter the green beans around it."},{"step":6,"text":"Roast for 22 to 25 minutes, until the potatoes are golden and tender and the chicken reads 165 F in the thickest part."},{"step":7,"text":"Rest the pan for 5 minutes. Spoon the pan juices over the chicken and vegetables before serving."},{"step":8,"text":"For leftovers, cool the food and store it in a covered container in the fridge for up to 3 days. Reheat until hot."}]'::jsonb, null, array['dinner', 'chicken', 'gluten_free', 'dairy_free', 'sheet_pan', 'kid_friendly', 'leftovers']::text[], 'american', 'catalog', null),
  ('6bd5914e-c86e-5b3f-9979-e39fdf0ebb68', null, 'Sheet Pan Salmon with Lemon Broccoli', 'Mild salmon fillets roast on one pan with tender broccoli and a bright lemon and garlic flavor. Gentle and familiar.', null, 'ai', null, 4, 10, 14, '[{"step":1,"text":"Heat the oven to 425 F. Line a rimmed 18 x 13 inch sheet pan with parchment."},{"step":2,"text":"In a large bowl, toss the broccoli with 2 tbsp olive oil, 1/2 tsp salt, and the pepper. Spread it on the pan in a single layer, leaving room in the center."},{"step":3,"text":"Roast the broccoli for 6 minutes."},{"step":4,"text":"Meanwhile, stir the remaining 1 tbsp olive oil, lemon zest, lemon juice, garlic, maple syrup, paprika, and remaining 1/4 tsp salt in a small bowl."},{"step":5,"text":"Pat the salmon dry. Push the broccoli to the sides and set the fillets in the center of the pan."},{"step":6,"text":"Spoon the lemon mixture over the salmon."},{"step":7,"text":"Roast 8 minutes more, until the salmon reaches 145 F in the thickest part and flakes easily, and the broccoli edges are lightly browned."},{"step":8,"text":"Serve the salmon with the broccoli and spoon any pan juices over the top."}]'::jsonb, null, array['dinner', 'fish', 'gluten_free', 'dairy_free', 'sheet_pan', 'kid_friendly']::text[], 'american', 'catalog', null),
  ('6905bd1b-236d-5356-bbb5-84860c564816', null, 'Sheet Pan Pork Sausage with Peppers and Potatoes', 'Mild pork sausage roasted with golden potatoes, sweet bell peppers, and onion on one pan. The flavors are savory and gentle with a little oregano and no heat.', null, 'ai', null, 4, 12, 23, '[{"step":1,"text":"Heat the oven to 450 F. Line a large rimmed sheet pan with parchment paper."},{"step":2,"text":"Cut the potatoes into small pieces so they cook fast. Put them on the pan."},{"step":3,"text":"Add the peppers and onion to the pan. Drizzle with the olive oil."},{"step":4,"text":"Sprinkle with the oregano, garlic powder, salt, and pepper. Toss well and spread in a single layer."},{"step":5,"text":"Roast for 10 minutes."},{"step":6,"text":"Take the pan out and push the vegetables aside. Add the sausage pieces and stir everything together."},{"step":7,"text":"Roast 12 to 13 minutes more, stirring once. The potatoes should be golden and tender, and the sausage should reach 160 F in the center."},{"step":8,"text":"Let the pan rest for 3 minutes, then serve."}]'::jsonb, null, array['dinner', 'pork', 'dairy_free', 'sheet_pan', 'kid_friendly']::text[], 'italian', 'catalog', null),
  ('22ff0b29-1669-52d6-84c9-6cbc46f44eb0', null, 'Sheet Pan Shrimp Fajitas with Corn Tortillas', 'Shrimp, bell peppers, and onion roast together on one pan with chili, cumin, and lime. Serve in warm corn tortillas for a smoky, tangy dinner.', null, 'ai', null, 4, 12, 12, '[{"step":1,"text":"Heat the oven to 450 F. Place a large rimmed sheet pan inside to heat while you prep."},{"step":2,"text":"Toss the peppers and onion on a cutting board with 2 tbsp of the oil, the chili powder, cumin, smoked paprika, garlic powder, 1/2 tsp of the salt, and the black pepper."},{"step":3,"text":"Carefully pull the hot pan out and spread the vegetables in a single layer. Roast for 7 minutes."},{"step":4,"text":"Pat the shrimp dry. Toss them in a bowl with the remaining 1 tbsp oil and the remaining 1/4 tsp salt."},{"step":5,"text":"Push the vegetables aside and add the shrimp to the pan in a single layer. Roast for 4 to 5 minutes, until the shrimp are pink and curled and the peppers are tender with browned edges."},{"step":6,"text":"Squeeze the juice of 1 lime over everything on the pan and toss gently."},{"step":7,"text":"Wrap the tortillas in foil and warm them in the oven for the last 4 minutes, or heat them in a dry skillet for 30 seconds per side."},{"step":8,"text":"Serve the shrimp and vegetables in the tortillas with cilantro and lime wedges."}]'::jsonb, null, array['dinner', 'shellfish', 'gluten_free', 'dairy_free', 'sheet_pan']::text[], 'mexican', 'catalog', null),
  ('480ba42f-cb05-5938-9ba2-cb52226687c1', null, 'Skillet Shrimp Pad Thai', 'Rice noodles tossed with shrimp, eggs, and bean sprouts in a tangy sweet tamarind-style sauce. Topped with crushed peanuts and lime.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Soak the rice noodles in a large bowl of hot tap water for 15 to 20 minutes, until bendy but still firm. Drain well."},{"step":2,"text":"Whisk the tamari, fish sauce, brown sugar, rice vinegar, lime juice, and red pepper flakes in a small bowl until the sugar dissolves."},{"step":3,"text":"Heat 1 tbsp oil in a 12-inch skillet over medium-high heat. Add the shrimp and cook 2 minutes per side, until pink and curled. Move them to a plate."},{"step":4,"text":"Add 1 tbsp oil and the garlic to the skillet. Cook 30 seconds, then pour in the eggs and scramble until just set, about 1 minute."},{"step":5,"text":"Add the remaining 1 tbsp oil, the drained noodles, and the sauce. Toss for 3 to 4 minutes, until the noodles are tender and have soaked up the sauce."},{"step":6,"text":"Return the shrimp to the pan with the bean sprouts and half of the green onions. Toss 1 minute, until the shrimp are hot and opaque."},{"step":7,"text":"Serve topped with the peanuts, the remaining green onions, and lime wedges."}]'::jsonb, null, array['dinner', 'shellfish', 'gluten_free', 'dairy_free', 'skillet']::text[], 'thai', 'catalog', null),
  ('365b031f-9c1b-5f59-b86d-76a923a38928', null, 'Spaghetti with Beef Tomato Sauce', 'Gluten-free spaghetti tossed in a mild, savory ground beef and tomato sauce. It is soft and familiar, with carrots cooked down into the sauce.', null, 'ai', null, 4, 10, 25, '[{"step":1,"text":"Bring the water and 1 tbsp salt to a boil in a large pot over high heat."},{"step":2,"text":"Heat the olive oil in a deep 12-inch skillet over medium heat. Add the onion and carrots and cook 5 minutes, until soft."},{"step":3,"text":"Stir in the garlic and cook 30 seconds. Add the ground beef and break it into small crumbles."},{"step":4,"text":"Cook the beef 6 to 8 minutes, until no pink remains and it reaches 160 F."},{"step":5,"text":"Stir in the crushed tomatoes, oregano, 1 tsp salt, and pepper. Simmer on medium-low 12 minutes, stirring now and then, until thick."},{"step":6,"text":"While the sauce simmers, cook the spaghetti in the boiling water for the time on the package, usually 8 to 10 minutes, until tender. Save 1/2 cup of the pasta water if you like, then drain."},{"step":7,"text":"Toss the spaghetti in the skillet with the sauce for 1 minute, until coated. Serve hot. To freeze, cool the pasta and sauce fully and store in airtight containers for up to 3 months."}]'::jsonb, null, array['dinner', 'beef', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly', 'freezer_friendly']::text[], 'italian', 'catalog', null),
  ('f5f73c6f-60ef-537e-9dc6-3d06cd35a208', null, 'Baked Spinach Mushroom Frittata', 'A thick Italian-style egg bake with tender spinach, browned mushrooms, and melted mozzarella and Parmesan. It is savory and mild, and it slices cleanly for leftovers.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Heat the oven to 400 F. Set a rack in the middle."},{"step":2,"text":"Warm the olive oil in a 10 inch oven-safe skillet over medium-high heat. Add the mushrooms and onion and cook for 6 to 7 minutes, until the mushrooms are browned and the liquid is gone."},{"step":3,"text":"Stir in the garlic for 30 seconds. Add the spinach in handfuls and cook for 2 minutes, until wilted."},{"step":4,"text":"Whisk the eggs, milk, salt, pepper, and oregano in a large bowl until smooth. Stir in the mozzarella and half of the Parmesan."},{"step":5,"text":"Pour the egg mixture into the skillet and stir once to spread the vegetables evenly. Sprinkle the rest of the Parmesan on top."},{"step":6,"text":"Bake for 16 to 18 minutes, until the center is set and no longer jiggles, and the top is lightly golden."},{"step":7,"text":"Rest for 5 minutes, then cut into 8 wedges. Cool leftovers, cover, and refrigerate for up to 4 days. Reheat in a 300 F oven or microwave until hot."}]'::jsonb, null, array['dinner', 'eggs', 'vegetarian', 'gluten_free', 'bake', 'leftovers']::text[], 'italian', 'catalog', null),
  ('7fafdf11-c6b6-5782-99cf-428b45c61f92', null, 'Spinach Ricotta Stuffed Shells in Marinara', 'Jumbo pasta shells filled with mild spinach and ricotta, baked in tomato sauce under melted mozzarella. Creamy, cheesy, and gentle in flavor.', null, 'ai', null, 4, 25, 35, '[{"step":1,"text":"Heat the oven to 375 F. Bring a large pot of water to a boil and stir in 1 tbsp salt."},{"step":2,"text":"Boil the shells for 8 minutes, until bendy but still firm. Drain and spread them on a tray so they do not stick."},{"step":3,"text":"Squeeze the spinach in a clean towel until very dry. Chop it finely so no long strands remain."},{"step":4,"text":"In a large bowl, mix the spinach, ricotta, 1 cup mozzarella, Parmesan, egg, 1/2 tsp salt, pepper, and nutmeg until smooth."},{"step":5,"text":"Spread 1 cup of marinara over the bottom of a 9 by 13 inch baking dish."},{"step":6,"text":"Spoon about 2 tablespoons of filling into each shell. Set the shells open side up in the dish."},{"step":7,"text":"Pour the remaining marinara over and around the shells. Sprinkle with the remaining 1 cup mozzarella."},{"step":8,"text":"Cover with foil and bake 20 minutes. Uncover and bake 10 to 15 minutes more, until the cheese is melted and golden and the sauce bubbles at the edges."},{"step":9,"text":"Rest 5 minutes before serving. To freeze, cool fully, wrap tightly, and reheat covered at 350 F until hot in the center."}]'::jsonb, null, array['dinner', 'cheese', 'vegetarian', 'bake', 'kid_friendly', 'freezer_friendly']::text[], 'italian', 'catalog', null),
  ('30a01fc0-daeb-5975-b864-62f3ca825cfe', null, 'One Pot Stovetop Mac and Cheese with Broccoli', 'Creamy elbow macaroni cooked in one pot with sharp cheddar and tender broccoli. The flavor is mild and cheesy, with a smooth sauce kids know well.', null, 'ai', null, 4, 10, 20, '[{"step":1,"text":"Add the water, milk, butter, macaroni, salt, garlic powder, mustard powder, and pepper to a large deep skillet or Dutch oven. Bring to a boil over medium-high heat, stirring often."},{"step":2,"text":"Reduce the heat to medium. Simmer for 8 minutes, stirring every minute or two so the pasta does not stick."},{"step":3,"text":"Stir in the broccoli florets. Cook for 3 to 4 minutes, until the pasta is tender and the broccoli is bright green and soft when pierced with a fork."},{"step":4,"text":"Most of the liquid should be absorbed, leaving a thin, creamy sauce. If the pot looks dry, add a splash of water."},{"step":5,"text":"Remove the pot from the heat. Add the cheddar a handful at a time, stirring until melted and smooth."},{"step":6,"text":"Let the mac and cheese stand for 3 minutes to thicken. Serve hot."}]'::jsonb, null, array['dinner', 'cheese', 'vegetarian', 'one_pot', 'kid_friendly', 'pantry']::text[], 'american', 'catalog', null),
  ('3a034f67-d4f2-570d-924a-f8415ace4759', null, 'Rice and Zucchini Stuffed Bell Peppers', 'Bell pepper halves baked with a filling of rice, zucchini, and tomatoes, seasoned with oregano and lemon. Soft, savory, and a little sweet.', null, 'ai', null, 4, 25, 40, '[{"step":1,"text":"Heat the oven to 375 F. Set the pepper halves cut side up in a 9 by 13 inch baking dish."},{"step":2,"text":"Heat 2 tbsp olive oil in a large skillet over medium heat. Cook the onion for 5 minutes, until soft."},{"step":3,"text":"Add the garlic and zucchini. Cook for 4 minutes, until the zucchini starts to soften."},{"step":4,"text":"Stir in the diced tomatoes with their juice, oregano, cumin, salt, and pepper. Simmer for 5 minutes, until thick."},{"step":5,"text":"Remove the pan from the heat. Stir in the cooked rice, lemon juice, and parsley."},{"step":6,"text":"Spoon the filling into the pepper halves, packing it in lightly. Pour the water into the bottom of the dish."},{"step":7,"text":"Drizzle the peppers with the remaining 1 tbsp olive oil. Cover the dish tightly with foil."},{"step":8,"text":"Bake for 25 minutes. Remove the foil and bake 10 to 15 minutes more, until the peppers are tender when pierced with a knife and the tops are lightly browned."}]'::jsonb, null, array['dinner', 'vegetables', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'bake']::text[], 'mediterranean', 'catalog', null),
  ('c20f4f4b-ca63-52cc-a52f-9fce63b4566a', null, 'Skillet Sweet and Sour Tofu with Pineapple', 'Pan-fried tofu cubes and bell peppers in a mild, glossy sweet and sour sauce with pineapple, served over rice. The flavor is sweet and tangy with no heat.', null, 'ai', null, 4, 15, 15, '[{"step":1,"text":"Combine the rice, water, and 1/2 tsp salt in a medium pot. Bring to a boil, cover, and cook on low for 15 minutes until the water is absorbed and the rice is tender."},{"step":2,"text":"Pat the tofu cubes dry and toss them with 3 tbsp cornstarch in a bowl until coated."},{"step":3,"text":"Drain the pineapple juice into a small bowl, keeping the chunks aside. Whisk in the ketchup, vinegar, brown sugar, soy sauce, and 1 tsp cornstarch until smooth."},{"step":4,"text":"Heat the oil in a 12 inch nonstick skillet over medium-high heat. Add the tofu in one layer and cook 8 minutes, turning, until golden and crisp on most sides."},{"step":5,"text":"Move the tofu to a plate. Add the bell peppers to the skillet and cook 3 minutes until bright and just tender."},{"step":6,"text":"Stir the sauce and pour it into the skillet. Simmer 2 minutes until it thickens and coats a spoon."},{"step":7,"text":"Add the tofu and pineapple chunks. Stir gently for 1 minute until hot, then serve over the rice."}]'::jsonb, null, array['dinner', 'tofu', 'vegetarian', 'vegan', 'dairy_free', 'skillet', 'kid_friendly']::text[], 'chinese', 'catalog', null),
  ('df2d5f35-f567-5b03-99c3-df76191e0756', null, 'Thai Basil Chicken with Chiles and Garlic', 'A fast skillet stir fry of chicken with garlic, red chiles, and Thai basil in a salty-sweet sauce. Served over jasmine rice. It is savory, spicy, and fragrant.', null, 'ai', null, 4, 15, 15, '[{"step":1,"text":"Rinse the rice in a fine strainer until the water runs mostly clear. Add it to a medium pot with the water and salt."},{"step":2,"text":"Bring the rice to a boil, then cover and reduce the heat to low. Cook for 15 minutes, then turn off the heat and let it steam, covered, while you cook the chicken."},{"step":3,"text":"Stir the soy sauce, oyster sauce, fish sauce, and brown sugar together in a small bowl until the sugar dissolves."},{"step":4,"text":"Heat the oil in a 12 inch skillet over high heat until it shimmers. Add the chicken in a single layer and cook for 4 minutes, stirring once or twice, until browned in spots."},{"step":5,"text":"Add the garlic, chiles, and bell pepper. Stir fry for 2 minutes until the garlic is fragrant and the pepper is just tender."},{"step":6,"text":"Pour in the sauce and cook for 1 to 2 minutes, until it coats the chicken and the chicken reaches 165 F in the thickest pieces."},{"step":7,"text":"Turn off the heat and stir in the basil until just wilted, about 30 seconds."},{"step":8,"text":"Fluff the rice with a fork and divide it among four bowls. Spoon the chicken and sauce over the top."}]'::jsonb, null, array['dinner', 'chicken', 'dairy_free', 'skillet']::text[], 'thai', 'catalog', null),
  ('d23810bd-09ea-5da9-90f9-882f34e9cbe6', null, 'Tofu Scramble Tacos with Peppers', 'Soft corn tortillas filled with a mild, golden tofu scramble and sweet sauteed peppers and onions. Gentle flavor with no heat, and a texture kids know from scrambled eggs.', null, 'ai', null, 4, 10, 15, '[{"step":1,"text":"Heat the olive oil in a large 12-inch skillet over medium heat. Add the onion and peppers."},{"step":2,"text":"Cook for 6 to 7 minutes, stirring often, until the vegetables are soft and the onion is lightly golden."},{"step":3,"text":"Crumble the tofu into the skillet with your hands into small, bite-size pieces."},{"step":4,"text":"Add the cumin, garlic powder, turmeric, salt, and pepper. Stir to coat the tofu evenly in yellow."},{"step":5,"text":"Cook for 6 to 8 minutes, stirring now and then, until the tofu is hot and any liquid in the pan has cooked off."},{"step":6,"text":"Warm the tortillas one at a time in a dry pan over medium heat for 20 to 30 seconds per side, until soft and pliable."},{"step":7,"text":"Spoon the scramble into the tortillas and top with avocado slices. Serve right away."}]'::jsonb, null, array['dinner', 'tofu', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly']::text[], 'mexican', 'catalog', null),
  ('9dac7382-225a-558c-8053-e6a7dc1abea1', null, 'Tofu Sweet Potato Spinach Coconut Curry', 'A one pot Indian-style curry with tofu, sweet potato, and spinach in a creamy coconut and tomato sauce. Warm, mildly spiced, and better the next day.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Heat the coconut oil in a large deep skillet or Dutch oven over medium heat. Add the onion and cook 4 minutes, until soft."},{"step":2,"text":"Stir in the garlic, ginger, curry powder, turmeric, and cumin. Cook 1 minute, until fragrant."},{"step":3,"text":"Add the tofu and sweet potatoes. Stir to coat in the spices and cook 2 minutes."},{"step":4,"text":"Pour in the diced tomatoes with their juice, the coconut milk, the water, and the salt. Stir and scrape up any browned bits."},{"step":5,"text":"Bring to a simmer, then cover and reduce the heat to medium-low. Cook 12 to 15 minutes, stirring once or twice, until a fork slides easily into the sweet potato."},{"step":6,"text":"Add the spinach by handfuls and stir until wilted, about 2 minutes."},{"step":7,"text":"Taste and add a pinch more salt if needed. Serve hot, or cool and store in a covered container in the fridge for up to 4 days."}]'::jsonb, null, array['dinner', 'tofu', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot', 'leftovers']::text[], 'indian', 'catalog', null),
  ('7f66f021-8168-5f34-943b-46c6d9ff445f', null, 'One Pot Lemon Tuna Pasta with Peas', 'A quick Italian-style pasta cooked in one pot with canned tuna, sweet peas, and a little lemon and capers. It tastes mild, bright, and lightly briny.', null, 'ai', null, 4, 10, 15, '[{"step":1,"text":"Heat the olive oil in a large deep skillet or pot over medium heat. Add the garlic and cook for 30 seconds until fragrant but not browned."},{"step":2,"text":"Add the penne, water, salt, and oregano. Bring to a boil over high heat."},{"step":3,"text":"Reduce to a steady simmer and cook for 9 to 11 minutes, stirring often, until the pasta is tender and most of the water is absorbed."},{"step":4,"text":"Stir in the frozen peas and cook for 2 minutes until hot and bright green."},{"step":5,"text":"Add the tuna, capers, lemon zest, and lemon juice. Break the tuna into small flakes as you stir."},{"step":6,"text":"Cook for 1 to 2 minutes until the tuna is warm. Add a splash of water if the pasta looks dry."},{"step":7,"text":"Season with the black pepper and stir in the parsley. Serve hot."}]'::jsonb, null, array['dinner', 'fish', 'dairy_free', 'one_pot', 'kid_friendly', 'pantry']::text[], 'italian', 'catalog', null),
  ('7c2a1d5a-ca6c-529b-932b-70253a595c43', null, 'Turkey Burrito Bowls', 'Ground turkey, rice, black beans, and corn topped with mild salsa. The flavors are savory and gentle, with no heat. The bowls reheat well the next day.', null, 'ai', null, 4, 10, 20, '[{"step":1,"text":"Combine the rice, water, and 1/2 tsp of the salt in a medium saucepan. Bring to a boil, then cover and cook on low for 15 minutes until the water is absorbed."},{"step":2,"text":"While the rice cooks, heat the oil in a large skillet over medium heat. Add the onion and cook 4 minutes until soft."},{"step":3,"text":"Add the turkey to the skillet and break it up with a spoon. Cook 6 to 7 minutes until no pink remains."},{"step":4,"text":"Stir in the cumin, paprika, garlic powder, pepper, and the remaining 1/2 tsp salt. Cook 1 minute."},{"step":5,"text":"Add the black beans, corn, and salsa. Simmer 5 minutes until the corn is hot and the turkey reads 165 F on a thermometer."},{"step":6,"text":"Fluff the rice with a fork. Divide the rice among four bowls and top with the turkey mixture."},{"step":7,"text":"For leftovers, cool the rice and turkey mixture and store them in airtight containers in the fridge for up to 3 days. Reheat until steaming hot."}]'::jsonb, null, array['dinner', 'turkey', 'gluten_free', 'dairy_free', 'skillet', 'kid_friendly', 'leftovers']::text[], 'mexican', 'catalog', null),
  ('167513be-8f12-56f4-8bcc-018738fe40ab', null, 'Baked Turkey Meatballs with Marinara and Spaghetti', 'Soft baked turkey meatballs in a mild tomato sauce over spaghetti. The meatballs are tender and lightly seasoned with garlic and parmesan.', null, 'ai', null, 4, 15, 20, '[{"step":1,"text":"Heat the oven to 425 F. Line a rimmed baking sheet with parchment paper."},{"step":2,"text":"In a large bowl, combine the turkey, breadcrumbs, parmesan, egg, garlic, oregano, 3/4 tsp salt, and pepper. Mix gently with your hands until just combined."},{"step":3,"text":"Roll the mixture into 20 meatballs, about 1 1/2 inches wide. Place them on the baking sheet."},{"step":4,"text":"Bake for 16 to 18 minutes, until browned and an instant-read thermometer inserted in the center reads 165 F."},{"step":5,"text":"While the meatballs bake, bring the water and 1 tbsp salt to a boil in a large pot. Cook the spaghetti for 9 to 10 minutes, until tender, then drain."},{"step":6,"text":"Warm the marinara in a large saucepan over medium heat for 5 minutes, until steaming."},{"step":7,"text":"Add the baked meatballs to the sauce and stir gently to coat. Simmer for 2 minutes."},{"step":8,"text":"Divide the spaghetti among four plates and top with the meatballs and sauce. Cool leftovers before freezing in airtight containers."}]'::jsonb, null, array['dinner', 'turkey', 'bake', 'kid_friendly', 'freezer_friendly']::text[], 'italian', 'catalog', null)
insert into public.recipes (id, household_id, title, description, image_url, source_type, source_url, servings, prep_min, cook_min, instructions, nutrition, tags, cuisine, visibility, created_by)
values
  ('0ba45c14-4988-5438-b184-efe7214c4c43', null, 'Turkey Sweet Potato Kale Skillet', 'Ground turkey, diced sweet potato, and tender kale cooked together in one skillet with cumin and paprika. Savory and lightly smoky, and it reheats well.', null, 'ai', null, 4, 15, 15, '[{"step":1,"text":"Heat the olive oil in a large 12 inch skillet with a lid over medium-high heat. Add the onion and sweet potatoes."},{"step":2,"text":"Cook for 5 minutes, stirring now and then, until the edges start to brown."},{"step":3,"text":"Push the vegetables to the sides. Add the turkey to the center and break it up with a spoon."},{"step":4,"text":"Stir in the garlic, cumin, smoked paprika, salt, and pepper. Cook for 4 minutes, until the turkey is no longer pink."},{"step":5,"text":"Pour in the water and scrape up any browned bits. Cover and cook for 4 minutes, until the sweet potatoes are nearly tender."},{"step":6,"text":"Add the kale in handfuls and stir until it wilts. Cover and cook 2 more minutes."},{"step":7,"text":"Check that the turkey reads 165 F and a sweet potato cube is soft when pierced with a fork. Serve hot, or cool and refrigerate for up to 4 days."}]'::jsonb, null, array['dinner', 'turkey', 'gluten_free', 'dairy_free', 'skillet', 'leftovers']::text[], 'american', 'catalog', null),
  ('46b3cc71-b077-58d7-8eb0-3ee84002694a', null, 'Tuscan White Bean and Kale Soup', 'A brothy one pot soup of creamy white beans, tender kale, garlic, and rosemary. It tastes savory and herbal, with a little brightness from lemon.', null, 'ai', null, 4, 10, 23, '[{"step":1,"text":"Heat the olive oil in a large pot over medium heat. Add the onion and carrots and cook for 5 minutes, stirring often, until the onion is soft."},{"step":2,"text":"Stir in the garlic, rosemary, and red pepper flakes. Cook for 1 minute until fragrant."},{"step":3,"text":"Add the beans, diced tomatoes with their juices, and vegetable broth. Bring to a boil over high heat."},{"step":4,"text":"Reduce the heat to medium-low. Simmer for 10 minutes, uncovered."},{"step":5,"text":"Use the back of a spoon to mash about a cup of the beans against the side of the pot. This thickens the soup."},{"step":6,"text":"Stir in the kale, salt, and black pepper. Simmer for 6 to 8 minutes, until the kale is tender and dark green."},{"step":7,"text":"Remove the pot from the heat and stir in the lemon juice. Taste and add more salt if needed."},{"step":8,"text":"Ladle into bowls. For storage, cool fully, then refrigerate up to 4 days or freeze up to 3 months."}]'::jsonb, null, array['dinner', 'beans', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'one_pot', 'pantry', 'leftovers', 'freezer_friendly']::text[], 'italian', 'catalog', null)
